-- maintenance/purge-rate-limits
-- Deletes flood-limit counters older than the given time (30 days, SPEC 12.3).
--
-- Parameters, with the example values used to render this file:
--   $1 = "2026-10-14T00:00:00.000Z"
--
-- Generated by `pnpm db:queries` from lib/db/queries/rate-limit.ts. Do not edit by hand.

delete
from "rate_limits"
where "rate_limits"."window_start" < $1
returning "key";
